'use strict';
(function(root){
const specs={Zinc:{unit:'t',priceUnit:'USD/t',demand:40000,capacity:50000,buffer:1000,price:2900,premium:155,freight:35,depot:1200,fx:84,arrivals:10000},Lead:{unit:'t',priceUnit:'USD/t',demand:12000,capacity:15000,buffer:300,price:1900,premium:120,freight:35,depot:1200,fx:84,arrivals:3000},Silver:{unit:'kg',priceUnit:'USD/kg',demand:10000,capacity:15000,buffer:500,price:2500,premium:5,freight:2,depot:20,fx:84,arrivals:2000}};
const zero=()=>({demandShock:0,priceShock:0,premiumShift:0,freightShift:0,fxShock:0,duty:0,deferral:0,delay:0});
function eligible(data,metal,review){return data.cases.filter(c=>c.metals.includes(metal)&&c.published<=review&&c.eventEnd>=data.windowStart&&c.eventEnd<=data.asOf);}
function calculate(metal,changes){if(!specs[metal])throw Error('Unsupported metal');const p=specs[metal],a={...zero(),...changes};const ranges={demandShock:[-50,50],priceShock:[-50,100],premiumShift:[-p.premium,1000],freightShift:[-p.freight,1000],fxShock:[-50,50],duty:[0,100],deferral:[0,100],delay:[0,90]};for(const [k,[lo,hi]] of Object.entries(ranges)){if(!Number.isFinite(a[k])||a[k]<lo||a[k]>hi)throw Error('Scenario input outside permitted range: '+k);}const fx=p.fx*(1+a.fxShock/100),baselineParity=(p.price+p.premium+p.freight)*p.fx+p.depot,stressedParity=(p.price*(1+a.priceShock/100)+p.premium+a.premiumShift+p.freight+a.freightShift)*fx*(1+a.duty/100)+p.depot;const deferred=p.arrivals*a.deferral/100;const rows=[0,1,2].map(i=>{const baseline=p.demand*(1+.02*i),demand=baseline*(1+a.demandShock/100),booked=p.demand*[.60,.45,.30][i],baseDomestic=Math.min(p.capacity,Math.max(baseline,booked)+p.buffer),domestic=Math.min(p.capacity,Math.max(demand,booked)+p.buffer);return {month:i+1,baseline,demand,booked,open:Math.max(0,demand-booked),baseDomestic,domestic,baseExport:p.capacity-baseDomestic,export:p.capacity-domestic,unserved:Math.max(0,Math.max(demand,booked)-p.capacity),bookingException:booked>demand,baseArrivals:p.arrivals,arrivals:p.arrivals+(i===0?-deferred:i===1?deferred:0)};});return {metal,unit:p.unit,priceUnit:p.priceUnit,assumptions:a,baseline:{...p,duty:0},baselineParity,stressedParity,parityDelta:stressedParity-baselineParity,deferred,rows,totalBaseline:rows.reduce((s,r)=>s+r.baseline,0),totalStressed:rows.reduce((s,r)=>s+r.demand,0)};}
const api={specs,zero,eligible,calculate};if(typeof module!=='undefined'&&module.exports)module.exports=api;if(!root||!root.document)return;
let metal='Zinc',review='2026-10-24',eventId='zinc-smelters',changes=zero(),classification='Unchanged illustrative baseline',refresh=()=>{};
const D=root.HZLEventData,esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),n=(x,d=0)=>Number(x).toLocaleString('en-IN',{maximumFractionDigits:d,minimumFractionDigits:d});
const card=(t,sub,b)=>`<section class="card"><div class="card-head"><div><h2>${esc(t)}</h2><p>${esc(sub)}</p></div></div>${b}</section>`;
const table=(heads,rows)=>`<div class="table-wrap"><table><thead><tr>${heads.map(h=>`<th scope="col">${esc(h)}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(v=>`<td>${v}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
const metric=(t,v,u,h)=>`<div class="kpi"><div class="kpi-label">${esc(t)}</div><div class="value">${v} <span class="unit">${esc(u)}</span></div><div class="hint">${esc(h)}</div></div>`;
function selected(){return eligible(D,metal,review).find(c=>c.id===eventId);}
function chart(r){const max=Math.max(...r.rows.flatMap(x=>[x.baseline,x.demand]))*1.12||1;return `<svg viewBox="0 0 650 260" class="chart" role="img" aria-label="Three-month illustrative baseline and manual demand scenario in ${r.unit}">${[0,.5,1].map(v=>`<line x1="65" x2="610" y1="${210-170*v}" y2="${210-170*v}" stroke="#dfe6df"/><text x="5" y="${214-170*v}">${n(max*v)}</text>`).join('')}${['baseline','demand'].map((key,j)=>`<polyline points="${r.rows.map((x,i)=>`${85+i*245},${210-170*x[key]/max}`).join(' ')}" fill="none" stroke="${j?'#b67c35':'#176c50'}" stroke-width="3" ${j?'stroke-dasharray="8 4"':''}/>${r.rows.map((x,i)=>`<circle cx="${85+i*245}" cy="${210-170*x[key]/max}" r="4" fill="${j?'#b67c35':'#176c50'}"><title>Month ${i+1} ${key}: ${n(x[key])} ${r.unit}</title></circle>`).join('')}`).join('')}${r.rows.map((x,i)=>`<text x="${85+i*245}" y="245" text-anchor="middle">Month ${i+1}</text>`).join('')}</svg><div class="legend"><span><i class="key"></i>Illustrative baseline</span><span>┄ Manual stress</span><span>${esc(r.unit)} · no model prediction or probability</span></div>`;}
function field(k,label,min,max,step='any'){return `<div class="field"><label for="lab-${k}">${esc(label)}</label><input id="lab-${k}" name="${k}" type="number" required min="${min}" max="${max}" step="${step}" value="${changes[k]}"></div>`;}
function render(ctx){refresh=ctx.refresh;const cases=eligible(D,metal,review);if(!cases.some(c=>c.id===eventId))eventId=cases[0]?.id||'';const c=selected(),p=specs[metal];const filters=`<div class="event-controls"><div><label for="lab-metal">Case metal</label><select id="lab-metal">${Object.keys(specs).map(m=>`<option ${m===metal?'selected':''}>${m}</option>`).join('')}</select></div><div><label for="lab-review">Evidence available by</label><input id="lab-review" type="date" min="2024-10-24" max="2026-10-24" value="${review}"></div><div class="event-case-select"><label for="lab-case">Historical case</label><select id="lab-case" ${cases.length?'':'disabled'}>${cases.length?cases.map(x=>`<option value="${x.id}" ${x.id===eventId?'selected':''}>${esc(x.title)}</option>`).join(''):'<option>No published case by this date</option>'}</select></div></div><div class="context-line">Reviewed window: 24 Oct 2024–24 Oct 2026 · ${cases.length} eligible case(s) · day-level report availability filter</div>`;
if(!c)return filters+'<div class="empty">No reviewed case for this metal was published by the selected date. Choose a later evidence date. Later reports are excluded from this view and its export.</div>';
const r=calculate(metal,changes),evidence=card(c.title,`${c.period} · published ${c.published} · ${c.source}`,`<p class="event-fact">${esc(c.fact)}</p><div class="event-evidence"><div><strong>Forecast input</strong><p>${esc(c.inputs)}</p></div><div><strong>Commercial review</strong><p>${esc(c.decision)}</p></div></div><p class="event-limit">${esc(c.limit)}</p><a href="${esc(c.url)}" target="_blank" rel="noopener noreferrer">Read original source${c.page?' · page '+esc(c.page):''} ↗</a>`);
const form=card('Manual scenario inputs',`${classification} · changes below are not inferred from the historical event`,`<div class="actions"><button data-lab-action="example">Try illustrative stress</button><button class="secondary" data-lab-action="reset">Reset changes to zero</button></div><form data-lab-form><div class="form-grid">${field('demandShock','Domestic order change (%)',-50,50)}${field('priceShock','Metal reference change (%)',-50,100)}${field('premiumShift',`Premium change (${p.priceUnit})`,-p.premium,1000)}${field('freightShift',`Freight change (${p.priceUnit})`,-p.freight,1000)}${field('fxShock','FX change (%)',-50,50)}${field('duty','Scenario duty (%) · baseline 0%',0,100)}${field('deferral','Month-1 arrivals deferred to month 2 (%)',0,100)}${field('delay','Indicative ETA delay (days)',0,90,1)}</div><button type="submit">Compare with baseline</button><p class="mini">Arrival deferral is entered separately from delay. No automatic day-to-volume conversion. Scenario duty is hypothetical, not a prevailing rate.</p></form>`);
const outcomes=`<div class="kpis">${metric('Three-month orders',n(r.totalStressed),r.unit,'Manual scenario; baseline '+n(r.totalBaseline))}${metric('Month-1 domestic reserve',n(r.rows[0].domestic),r.unit,'Demand / bookings plus buffer, capped at capacity')}${metric('Month-1 residual export',n(r.rows[0].export),r.unit,'Availability only; market access and netback still needed')}${metric('Parity change',(r.parityDelta>0?'+':'')+n(r.parityDelta,2),'INR/'+r.unit,'Scenario minus illustrative baseline')}</div>`;
return filters+evidence+outcomes+`<div class="grid equal">${card('Monthly order comparison','Illustrative commercial sensitivity, separate from observed market evidence',chart(r))}${card('Visible decision logic','A repeatable review with explicit boundaries',`<ol class="event-logic"><li>Confirm source date, geography, grade and exposure.</li><li>Enter a reviewed sensitivity or retain zero change.</li><li>Recalculate orders, parity and arrival buckets separately.</li><li>Reserve domestic demand / bookings plus buffer.</li><li>Review export economics and approve the decision.</li></ol><p class="mini">No causal model, live feed or calibrated forecast interval is connected to this case library.</p>`)}</div>`+form+card('Three-month order and allocation output',`All quantities in ${r.unit}. Expected orders already include booked volume.`,table(['Month','Baseline orders','Scenario orders','Booked','Domestic reserve','Residual export','Unserved orders'],r.rows.map(x=>['Month '+x.month,n(x.baseline),n(x.demand),n(x.booked),n(x.domestic),n(x.export),n(x.unserved)+(x.bookingException?' · bookings exceed estimate':'')]))+`<p class="mini">Reserve = min(capacity, max(scenario orders, booked) + buffer). Buffer is a planning reservation, not an order.</p>`)+card('Shipment and landed-cost comparison','Scenario quantities and prices are hypothetical',table(['Measure','Baseline','Scenario'],[['Month-1 arrivals',n(p.arrivals)+' '+p.unit,n(r.rows[0].arrivals)+' '+p.unit],['Month-2 arrivals',n(p.arrivals)+' '+p.unit,n(r.rows[1].arrivals)+' '+p.unit],['Month-3 arrivals',n(p.arrivals)+' '+p.unit,n(r.rows[2].arrivals)+' '+p.unit],['Indicative ETA shift','0 days',n(changes.delay)+' days'],['Landed parity',n(r.baselineParity,2)+' INR/'+p.unit,n(r.stressedParity,2)+' INR/'+p.unit]]))+card('Assumptions and source timing','Inspectable baseline values and provenance',`<details><summary>Illustrative baseline and calculation method</summary>${table(['Input','Value'],Object.entries(p).map(([k,v])=>[esc(k),esc(v)]))}<p>Baseline monthly orders increase linearly by 2% of month-1 baseline per step. Bookings are fixed at 60%, 45% and 30% of month-1 baseline. Baseline duty is 0%. Simplified parity = (metal reference + premium + freight) × FX × (1 + duty) + depot. Silver uses kg and USD/kg throughout; zinc and lead use tonnes and USD/t. There is no precious-metal duty classification inference.</p></details><details><summary>Publication timing, source preview and limits</summary>${table(['Field','Reviewed value'],[['Observation period',esc(c.period)],['Event/period end',c.eventEnd],['Publication date',c.published],['Review date',review],['Selected channel',esc(c.channel)],['Original source',`<a href="${esc(c.url)}" target="_blank" rel="noopener noreferrer">${esc(c.source)}</a>`]])}<p>The selected report is available only on or after its publication date. This is a day-level demonstration, not a full timestamped historical information set. Source definitions and provisional estimates can change. Reporting lag remains visible.</p><p>World Bank material: World Bank, Commodity Markets Outlook, April 2026, CC BY 3.0 IGO. This is an adaptation; scenario views are the author’s and are not endorsed by the World Bank. Hinglish notes are not an official World Bank translation.</p></details>`)+`<div class="actions"><button data-lab-action="planning">Review in connected planning →</button><button class="secondary" data-lab-action="export">Export selected case and scenario</button></div><div id="lab-message" role="status"></div>`;
}
function snapshot(){const c=selected();return {asOf:D.asOf,reviewDate:review,classification:'Public historical evidence + hypothetical manual scenario',case:c?{...c,preset:undefined}:null,calculation:c?calculate(metal,changes):null,scenarioClassification:classification,methods:D.methods};}
function reset(){changes=zero();classification='Unchanged illustrative baseline';}
document.addEventListener('change',e=>{if(!e.target.id.startsWith('lab-'))return;if(e.target.id==='lab-metal'){metal=e.target.value;eventId='';reset();refresh();}if(e.target.id==='lab-review'){if(!e.target.checkValidity())return;review=e.target.value;eventId='';reset();refresh();}if(e.target.id==='lab-case'){eventId=e.target.value;reset();refresh();}});
document.addEventListener('submit',e=>{if(!e.target.matches('[data-lab-form]'))return;e.preventDefault();if(!e.target.reportValidity())return;const v={};for(const el of e.target.querySelectorAll('input'))v[el.name]=Number(el.value);try{calculate(metal,v);changes=v;classification='User-entered hypothetical sensitivity';refresh();}catch(err){document.querySelector('#lab-message').textContent=err.message;}});
document.addEventListener('click',e=>{const b=e.target.closest('[data-lab-action]');if(!b)return;const action=b.dataset.labAction;if(action==='planning'){const c=selected();if(c)root.HZLPlanning.queueFromCase(metal,c,changes);}if(action==='example'){const c=selected();if(!c)return;changes={...c.preset};classification='Illustrative preset; not estimated from event';refresh();}if(action==='reset'){reset();refresh();}if(action==='export'){const data=new Blob([JSON.stringify(snapshot(),null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(data);a.download='HZL-selected-event-scenario.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}});
root.HZLEventLab={render,snapshot,...api};
})(typeof window!=='undefined'?window:null);
